g.shout()

class PartyAnimal:
    def __init__(self, nam):
        self.name = nam
        self.x = 0

    def party(self):
        self.x = self.x + 1
        print(self.name, 'party', self.x)

class CricketFan(PartyAnimal):
    points = 0

j = CricketFan('Jim')
j.party()
print('points' in dir(j))
